# Create the output pattern
# Based on analysis: 3 parallel diagonal bands going down-left
# Start positions from row 4: col 2 for band 1, col 3 for band 3, col 4 for band 5

output = [[0]*20 for _ in range(20)]

# Band 1 (blue) starting at (4, 2)
for r in range(4, 20):
    c = 2 - (r - 4)
    if 0 <= c < 20:
        output[r][c] = 1

# Band 3 (green) starting at (4, 3) 
for r in range(4, 20):
    c = 3 - (r - 4)
    if 0 <= c < 20:
        output[r][c] = 3

# Band 5 (gray) starting at (4, 4)
for r in range(4, 20):
    c = 4 - (r - 4)
    if 0 <= c < 20:
        output[r][c] = 5

# Verify the bands don't overlap and visualize them
print("Output grid:")
for r in range(20):
    row_str = ""
    for c in range(20):
        if c == 2 and c+1 not in [2,3,4]:
            row_str += "."
        elif c == 3:
            row_str += "."
        elif c == 4:
            row_str += "."
        else:
            row_str += " "
    print(output[r])

# Now print with values
print("\nOutput grid with values:")
for r in range(20):
    row_str = ""
    for c in range(20):
        row_str += str(output[r][c]) + " "
    print(row_str)

